const items = $input.all();
if (items.length === 0) {
  return [{ json: { checkName: 'no_input', isSkipped: true } }];
}

const config = items[0].json;

// Поддержка checks как объекта или массива
let checks = [];
if (Array.isArray(config.checks)) {
  checks = config.checks.filter(c => c.enabled !== false);
} else if (config.checks && typeof config.checks === 'object') {
  if (config.checks.enabled !== false) {
    checks = [config.checks];
  }
}

if (checks.length === 0) {
  return [{ json: { checkName: 'no_active_checks', isSkipped: true } }];
}

return checks.map(check => {
  // Очищаем apiBaseUrl от пробелов
  const baseUrl = (config.apiBaseUrl || 'https://api.palatine.ru').trim();
  const url = baseUrl + $input.first().json.checks.endpoint;

  return {
    json: {
      // Метаданные — для логов и Telegram
      checkName: check.name || 'unknown',
      telegramChatId: config.telegramChatId,
      projectName: config.projectName,
      environment: config.environment,

      // Запрос
      method: check.method || 'POST',
      url: url,
      timeout: (check.timeoutSeconds || 15) * 1000,
      headers: {
        'User-Agent': 'n8n-healthcheck'
        // Authorization будет добавлен в HTTP Request через Expression
      },

      // Тело запроса
      payloadType: check.payloadType || 'file',
      fileUrl: check.payloadType === 'file' ? check.testData?.fileUrl : undefined,
      formDataFields: { ...check.testData },

      // Убираем fileUrl из полей формы, если он есть
      ...(check.payloadType === 'file' && check.testData?.fileUrl && {
        formDataFields: {
          ...check.testData,
          fileUrl: undefined
        }
      }),

      // Для Evaluate Result
      successCriteria: check.successCriteria || {}
    }
  };
});

return $input.all().map(item => {
  const json = item.json;

  // 1. Извлекаем данные в зависимости от структуры
  let status, body, executionTime, errorMessageFromRequest = '';
  let hasError = false;

  if (json.error) {
    // Случай: ошибка запроса (404, таймаут, DNS и т.д.)
    hasError = true;
    status = json.error.status || null;
    body = null;
    executionTime = json.executionTime || 0;
    errorMessageFromRequest = json.error.message || json.error.name || 'Unknown request error';
  } else {
    // Случай: запрос успешен, есть statusCode и body
    status = json.statusCode || json.status; // поддерживаем оба варианта
    body = json.body;
    executionTime = json.executionTime || 0;
  }

  // 2. Берём метаданные проверки
  const checkName = $('Prepare Request_tg').first().json.checkName || 'unknown';
  const successCriteria = json.successCriteria || {};

  // 3. Оцениваем результат
  let isOk = false;
  let errorMessage = '';

  try {
    const expectedStatus = successCriteria.statusCode || 200;

    // Если был провал запроса — сразу ошибка
    if (hasError) {
      errorMessage = `Request failed: ${errorMessageFromRequest}`;
    } else if (status !== expectedStatus) {
      errorMessage = `HTTP ${status} ≠ expected ${expectedStatus}`;
    } else if (!body || typeof body !== 'object') {
      errorMessage = 'Empty or invalid JSON response';
    } else {
      // Дополнительные проверки (для httpbin или Palatine)
      if (successCriteria.mustHaveFile) {
        const fileName = successCriteria.mustHaveFile;
        if (!body.files?.[fileName]) {
          errorMessage = `Missing file "${fileName}" in response`;
        } else if (successCriteria.fileContentContains) {
          const content = body.files[fileName];
          if (!content.includes(successCriteria.fileContentContains)) {
            errorMessage = `File "${fileName}" does not contain expected text`;
          }
        }
      }

      if (!errorMessage && successCriteria.mustHaveFormFields) {
        for (const field of successCriteria.mustHaveFormFields) {
          if (body.form?.[field] === undefined) {
            errorMessage = `Missing form field: "${field}"`;
            break;
          }
        }
      }
    }

    isOk = !errorMessage;

  } catch (e) {
    errorMessage = 'Evaluation error: ' + e.message;
  }

  return {
    json: {
      checkName,
      isOk,
      errorMessage: errorMessage || errorMessageFromRequest,
      latencyMs: executionTime,
      statusCode: status,
      // Для дебага:
      // rawError: json.error,
      // responseBody: body
    }
  };
});

